const s=/^(?:[A-Z]{2}[0-9]{6,8}|[0-9]{6,10})$/,r=/^[0-9]{11}$/,e=/^(?:[A-Z0-9]{16}|[0-9]{11})$/,o=/^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}$/;function a(t){return(t??"").trim().toUpperCase()}function i(t){const n=a(t);return n==="ITALY"||n==="ITALIA"}function A(t,n){return i(t)||i(n)}function I(t){const n=a(t).replace(/-/g,"");return!!n&&s.test(n)}function T(t){const n=a(t).replace(/\s/g,"");return!!n&&e.test(n)}function c(t){const n=a(t);return!!n&&r.test(n)}function u(t){return o.test((t??"").trim())}export{I as a,T as b,c,u as h,A as i};
